import "#app/polyfills"; // All polyfills MUST be loaded first for side effects
import "#init/init-manifest"; // initializes the manifest, must be done *before* i18n is initialized due to being used for caching
import "#app/i18n"; // Initializes i18n on import

import { InvertPostFX } from "#app/pipelines/invert";
import { isBeta, isDev } from "#constants/app-constants";
import { version } from "#package.json";
import Phaser from "phaser";
import BBCodeTextPlugin from "phaser3-rex-plugins/plugins/bbcodetext-plugin";
import InputTextPlugin from "phaser3-rex-plugins/plugins/inputtext-plugin";
import TransitionImagePackPlugin from "phaser3-rex-plugins/templates/transitionimagepack/transitionimagepack-plugin";
import UIPlugin from "phaser3-rex-plugins/templates/ui/ui-plugin";

if (isBeta || isDev) {
  document.title += " (Beta)";
}

async function startGame(): Promise<void> {
  const LoadingScene = (await import("./loading-scene")).LoadingScene;
  const BattleScene = (await import("./battle-scene")).BattleScene;
  const game = new Phaser.Game({
    type: Phaser.WEBGL,
    parent: "app",
    scale: {
      width: 1920,
      height: 1080,
      mode: Phaser.Scale.FIT,
    },
    plugins: {
      global: [
        {
          key: "rexInputTextPlugin",
          plugin: InputTextPlugin,
          start: true,
        },
        {
          key: "rexBBCodeTextPlugin",
          plugin: BBCodeTextPlugin,
          start: true,
        },
        {
          key: "rexTransitionImagePackPlugin",
          plugin: TransitionImagePackPlugin,
          start: true,
        },
      ],
      scene: [
        {
          key: "rexUI",
          plugin: UIPlugin,
          mapping: "rexUI",
        },
      ],
    },
    input: {
      mouse: {
        target: "app",
      },
      touch: {
        target: "app",
      },
      gamepad: true,
    },
    dom: {
      createContainer: true,
    },
    antialias: false,
    pipeline: [InvertPostFX] as unknown as Phaser.Types.Core.PipelineConfig,
    scene: [LoadingScene, BattleScene],
    version,
  });
  game.sound.pauseOnBlur = false;

  // ▼▼▼ PKRC 魔改 patch: 走查可观测句柄（第八阶段 A-1/B-1）▲▲▲
  // 🔴 **为什么需要**：本作全部 UI 渲染在单个 canvas 里，`document.body.innerText.length === 0`
  //   ⇒ **DOM 断言对游戏内画面完全失效**（U-11 的判断是对的）；`Phaser.GAMES` 在该构建下也不可用。
  //   走查要判「到达了哪个画面 / 战斗到第几波 / 谁还剩多少 HP」，只能读**真实状态**。
  //
  // ⚠️ 这是**纯观测**：只把已存在的 `game` 实例挂到一个只读全局，不创建、不修改、不驱动任何逻辑。
  //   去掉这一行不影响游戏任何行为；保留它只是让自动走查有可断言的锚点。
  //   `Object.defineProperty` 而非直接赋值 ⇒ 不可被业务代码意外覆盖。
  Object.defineProperty(window, "__PKRC_GAME__", {
    value: game,
    writable: false,
    configurable: false,
    enumerable: false,
  });
  // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲
}

try {
  await Promise.all([document.fonts.load("16px emerald"), document.fonts.load("10px pkmnems")]);
} catch (err) {
  console.error("Error loading fonts:", err);
} finally {
  await startGame();
}
